def _box(x0, x1, y0, y1, z0, z1):
    return Solid.makeBox(x1 - x0, y1 - y0, z1 - z0, Vector(x0, y0, z0))

def _zcyl(r, x, y, z0, z1):
    return Solid.makeCylinder(r, z1 - z0, Vector(x, y, z0), Vector(0, 0, 1))

def _xcyl(r, y, z, x0, x1):
    return Solid.makeCylinder(r, x1 - x0, Vector(x0, y, z), Vector(1, 0, 0))

def _ycyl(r, x, z, y0, y1):
    return Solid.makeCylinder(r, y1 - y0, Vector(x, y0, z), Vector(0, 1, 0))
s = _box(0, 117.6, 0, 38.7, 0, 5.9)
tri = cq.Workplane("XY").polyline([(11.7, 7.6), (26.1, 7.6), (18.9, 31.1)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(38.3, 31.1), (52.7, 31.1), (45.5, 7.6)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(64.9, 7.6), (79.3, 7.6), (72.1, 31.1)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(91.5, 31.1), (105.9, 31.1), (98.7, 7.6)]).close().extrude(5.9).val()
s = s.cut(tri)
result = s

