    return Solid.makeBox(x1 - x0, y1 - y0, z1 - z0, Vector(x0, y0, z0))

def _zcyl(r, x, y, z0, z1):
    return Solid.makeCylinder(r, z1 - z0, Vector(x, y, z0), Vector(0, 0, 1))

def _xcyl(r, y, z, x0, x1):
    return Solid.makeCylinder(r, x1 - x0, Vector(x0, y, z), Vector(1, 0, 0))

def _ycyl(r, x, z, y0, y1):
    return Solid.makeCylinder(r, y1 - y0, Vector(x, y0, z), Vector(0, 1, 0))
s = _box(0, 121.9, 0, 50.7, 0, 5.9)
tri = cq.Workplane("XY").polyline([(13.5, 8.7), (27.1, 8.7), (20.3, 42)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(40.6, 42), (54.2, 42), (47.4, 8.7)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(67.7, 8.7), (81.3, 8.7), (74.5, 42)]).close().extrude(5.9).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(94.8, 42), (108.4, 42), (101.6, 8.7)]).close().extrude(5.9).val()
s = s.cut(tri)
result = s

