s = s.cut(prof)
s = s.cut(_zcyl((5.9)/2, 13.4, 18.2, -1, (30.6 + 1)))
s = s.cut(_zcyl((5.9)/2, 71.2, 18.2, -1, (30.6 + 1)))
result = s

