    return Solid.makeBox(x1 - x0, y1 - y0, z1 - z0, Vector(x0, y0, z0))

def _zcyl(r, x, y, z0, z1):
    return Solid.makeCylinder(r, z1 - z0, Vector(x, y, z0), Vector(0, 0, 1))

def _xcyl(r, y, z, x0, x1):
    return Solid.makeCylinder(r, x1 - x0, Vector(x0, y, z), Vector(1, 0, 0))

def _ycyl(r, x, z, y0, y1):
    return Solid.makeCylinder(r, y1 - y0, Vector(x, y0, z), Vector(0, 1, 0))
body = Solid.makeCone((29.8)/2, (53.2)/2, 38.8, Vector(0, 0, 0), Vector(0, 0, 1))
rec = Solid.makeCone((18.6)/2, (45.8)/2, (39.8 - 6.2), Vector(0, 0, 6.2), Vector(0, 0, 1))
spout = _zcyl((15.4)/2, 0, 0, -12.9, 4)
s = body.fuse(spout)
s = s.cut(rec)
s = s.cut(_zcyl((8)/2, 0, 0, -13.9, 7.2))
rim = _zcyl((61.2)/2, 0, 0, 38.8, (38.8 + 4.6))
rim = rim.cut(_zcyl((45.8)/2, 0, 0, 38.8, ((38.8 + 4.6) + 1)))
s = s.fuse(rim)
result = s

