    return Solid.makeBox(x1 - x0, y1 - y0, z1 - z0, Vector(x0, y0, z0))

def _zcyl(r, x, y, z0, z1):
    return Solid.makeCylinder(r, z1 - z0, Vector(x, y, z0), Vector(0, 0, 1))

def _xcyl(r, y, z, x0, x1):
    return Solid.makeCylinder(r, x1 - x0, Vector(x0, y, z), Vector(1, 0, 0))

def _ycyl(r, x, z, y0, y1):
    return Solid.makeCylinder(r, y1 - y0, Vector(x, y0, z), Vector(0, 1, 0))
body = Solid.makeCone((34.6)/2, (54.2)/2, 39.7, Vector(0, 0, 0), Vector(0, 0, 1))
rec = Solid.makeCone((23.8)/2, (47)/2, (40.7 - 8.9), Vector(0, 0, 8.9), Vector(0, 0, 1))
spout = _zcyl((16.6)/2, 0, 0, -12.5, 4)
s = body.fuse(spout)
s = s.cut(rec)
s = s.cut(_zcyl((9.4)/2, 0, 0, -13.5, 9.9))
rim = _zcyl((62.4)/2, 0, 0, 39.7, (39.7 + 3.4))
rim = rim.cut(_zcyl((47)/2, 0, 0, 39.7, ((39.7 + 3.4) + 1)))
s = s.fuse(rim)
result = s

